import { describe, expect, test } from 'bun:test'

import {
  WORKER_BUSY_STALE_MS,
  computeWorkerStatus,
  getPinnedWorkerShorts,
  isWorkerBusy,
  safeExtractServedFolderDir,
} from '../workerRegistry.js'

// Porte de `Oe`, `Qe` y `Ue.get status()`/`isBusy()` (`chunk-92tvramn.js`,
