    expect(
      computeWorkerStatus({ pid: undefined, startedAt: 0, config: {}, servedSessionsCount: 0 }),
    ).toBeNull()
  })

  test('sin servedFolder cuando servedSessionsCount es 0', () => {
    expect(
      computeWorkerStatus({
        pid: 123,
        startedAt: 456,
