        servedSessionsCount: 3,
      }),
    ).toEqual({ pid: 123, startedAt: 456 })
  })

  test('con servedFolder cuando hay sesiones servidas Y dir válido', () => {
    expect(
      computeWorkerStatus({
        pid: 123,
        startedAt: 456,
        config: { dir: '/repo' },
        servedSessionsCount: 3,
      }),
    ).toEqual({ pid: 123, startedAt: 456, servedFolder: { dir: '/repo', sessions: 3 } })
  })
})
